/**
 * Apply movement physics (groundMove/airMove) based on current-frame groundAngle.
 * This function should be called AFTER collision detection so that groundAngle
 * reflects the current frame's ground contact state.
 *
 * This is the key fix for physics oscillation - gravity decisions now use
 * current-frame collision data instead of previous-frame data.
 *
 * @param {Object} body - Physics body instance
 * @param {number} delta - Fixed timestep in seconds
 * @param {BufferBackedObject} sDynamic - Shared buffer view for this body
 * @param {number} index - Body index in the dynamic bodies array
 */
export function applyMovementPhysics(body: any, delta: number, sDynamic: BufferBackedObject, index: number): void;
/**
 * Process input and rotation for driving bodies (Phase 1 - before collision detection).
 * This handles gravity direction, body rotation, and angular velocity integration,
 * but does NOT apply groundMove/airMove (those are deferred to Phase 3).
 *
 * @param {Object} body - Physics body instance
 * @param {number} delta - Fixed timestep in seconds
 * @param {BufferBackedObject} sDynamic - Shared buffer view for this body
 * @param {number} index - Body index in the dynamic bodies array
 */
export function dynamicInputOnly(body: any, delta: number, sDynamic: BufferBackedObject, index: number): void;
/**
 * Process input and rotation for physics bodies (Phase 1 - before collision detection).
 * This handles gravity direction, body rotation, and angular velocity integration,
 * but does NOT apply groundMove/airMove (those are deferred to Phase 3).
 *
 * @param {Object} body - Physics body instance
 * @param {number} delta - Fixed timestep in seconds
 * @param {BufferBackedObject} sDynamic - Shared buffer view for this body
 * @param {number} index - Body index in the dynamic bodies array
 * @returns {boolean} True if processed, false if skipped (sleep)
 */
export function dynamicVelocityInputOnly(body: any, delta: number, sDynamic: BufferBackedObject, index: number): boolean;
/**
 * Update dynamic body physics for one simulation step.
 * - Velocity clipping is handled in trimeshSolver
 *
 * @param {Object} body - Physics body instance
 * @param {number} delta - Fixed timestep in seconds
 * @param {BufferBackedObject} sDynamic - Shared buffer view for this body
 * @param {number} index - Body index in the dynamic bodies array
 */
export function dynamic(body: any, delta: number, sDynamic: BufferBackedObject, index: number): void;
/**
 * Calculate velocity for dynamic body (gravity, friction, acceleration).
 * This is the first phase of physics - velocity calculation only, no position update.
 * Used by CCD modes to separate velocity calc from position updates.
 *
 * @param {Object} body - Physics body instance
 * @param {number} delta - Fixed timestep in seconds
 * @param {BufferBackedObject} sDynamic - Shared buffer view for this body
 * @param {number} index - Body index in the dynamic bodies array
 * @returns {boolean} True if velocity was calculated, false if skipped (sleep)
 */
export function dynamicVelocity(body: any, delta: number, sDynamic: BufferBackedObject, index: number): boolean;
/**
 * Apply position update for dynamic body.
 * This is the second phase of physics - moves body by velocity.
 * Can be called with fraction < 1.0 for CCD substeps or sweep.
 *
 * @param {Object} body - Physics body instance
 * @param {number} delta - Fixed timestep in seconds
 * @param {BufferBackedObject} sDynamic - Shared buffer view for this body
 * @param {number} index - Body index in the dynamic bodies array
 * @param {number} [fraction=1.0] - Fraction of movement to apply (0.0 to 1.0)
 */
export function dynamicPosition(body: any, delta: number, sDynamic: BufferBackedObject, index: number, fraction?: number): void;
